// The Inspector UI's files (path below the build → a module holding the file
// as base64), carried as modules so that bundlers and output file tracing
// (Next.js on Vercel) ship them with the code that serves them: files read
// from disk at runtime are left behind. Each is imported only when asked for. The published package's copy is generated by
// scripts/stage-inspector-overlay.mjs; in this monorepo there is none, and
// the UI is read from the inspector package's build instead.
export const INSPECTOR_UI_FILES: Readonly<
  Record<string, () => Promise<{ default: string }>>
> | null = null;
